import fs from 'node:fs';
import path from 'node:path';

// Collect full notices, not just SPDX identifiers, from the exact installed artifacts.
const sections = [
  'SaruMD third-party notices\nGenerated by scripts/licenses.mjs. See pnpm-lock.yaml / Cargo.lock.\n',
];
const seen = new Set();
const supplements = {
  'clipboard-win': 'BSL-1.0.txt',
  'webview2-com': 'webview2-rs-MIT.txt',
  'webview2-com-macros': 'webview2-rs-MIT.txt',
  'webview2-com-sys': 'webview2-rs-MIT.txt',
  'alloc-stdlib': 'alloc-stdlib-BSD.txt',
  selectors: 'MPL-2.0.txt',
  saxes: 'saxes-ISC.txt',
  keyv: 'keyv-MIT.txt',
  'natural-compare': 'natural-compare-MIT.txt',
};
function installedNodePackage(name) {
  const entry = fs
    .readdirSync('node_modules/.pnpm')
    .find((e) => e.startsWith(`${name.replace('/', '+')}@`));
  return entry
    ? path.join('node_modules/.pnpm', entry, 'node_modules', name)
    : undefined;
}
function addPackage(directory, name, version, license) {
  const key = `${name}@${version}`;
  if (seen.has(key)) return;
  seen.add(key);
  const notices = fs
    .readdirSync(directory)
    .filter(
      (file) =>
        /^(licen[cs]e|copying|copyright|notice)([._-]|$)/i.test(file) &&
        fs.statSync(path.join(directory, file)).isFile(),
    );
  sections.push(
    `\n${'='.repeat(72)}\n${key}\nLicense: ${typeof license === 'string' ? license : JSON.stringify(license)}\n`,
  );
  for (const file of notices)
    sections.push(
      `\n--- ${file} ---\n${fs.readFileSync(path.join(directory, file), 'utf8')}\n`,
    );
  if (!notices.length) {
    // Some packages (e.g. compiler output helpers) carry their notice under a subfolder.
    let found = false;
    for (const folder of ['licenses', 'license', 'LICENSES']) {
      for (const file of fs.existsSync(path.join(directory, folder))
        ? fs.readdirSync(path.join(directory, folder))
        : []) {
        const target = path.join(directory, folder, file);
        if (fs.statSync(target).isFile()) {
          sections.push(
            `\n--- ${folder}/${file} ---\n${fs.readFileSync(target, 'utf8')}\n`,
          );
          found = true;
        }
      }
    }
    const parentName = name.startsWith('@esbuild/')
      ? 'esbuild'
      : name.startsWith('@rollup/')
        ? 'rollup'
        : name.startsWith('@tauri-apps/cli-')
          ? '@tauri-apps/cli'
          : name === '@humanfs/types'
            ? '@humanfs/core'
            : undefined;
    const parent = parentName ? installedNodePackage(parentName) : undefined;
    if (parent) {
      for (const file of fs
        .readdirSync(parent)
        .filter((f) => /^licen[cs]e/i.test(f))) {
        sections.push(
          `\n--- upstream ${parentName}/${file} ---\n${fs.readFileSync(path.join(parent, file), 'utf8')}\n`,
        );
        found = true;
      }
    }
    if (name === 'tauri-plugin') {
      const parent = JSON.parse(
        fs.readFileSync(
          process.argv[2] ?? '.tools/cargo-metadata.json',
          'utf8',
        ),
      ).packages.find((p) => p.name === 'tauri');
      const parentDir = path.dirname(
        parent.manifest_path.replace(
          /^\/mnt\/([a-z])\//,
          (_, d) => `${d.toUpperCase()}:/`,
        ),
      );
      for (const file of fs
        .readdirSync(parentDir)
        .filter((f) => /^licen[cs]e/i.test(f))) {
        sections.push(
          `\n--- Tauri upstream ${file} ---\n${fs.readFileSync(path.join(parentDir, file), 'utf8')}\n`,
        );
        found = true;
      }
    }
    if (supplements[name]) {
      sections.push(
        `\n--- supplemental upstream notice (see docs/licenses/README.md) ---\n${fs.readFileSync(path.join('docs/licenses', supplements[name]), 'utf8')}\n`,
      );
      found = true;
    }
    for (const file of ['README.md', 'esrecurse.js', 'formatstack.js']) {
      const target = path.join(directory, file);
      if (!fs.existsSync(target)) continue;
      const content = fs.readFileSync(target, 'utf8');
      const start = content.search(/(?:^|\n)#+ Licen[cs]e|Copyright/i);
      if (start < 0) continue;
      const notice = file.endsWith('.js')
        ? content.slice(
            0,
            Math.max(
              content.indexOf('*/') + 2,
              content.indexOf('\nvar '),
              content.indexOf('\nmodule.exports'),
            ),
          )
        : content.slice(start);
      sections.push(`\n--- ${file} notice ---\n${notice}\n`);
      found = true;
    }
    if (!found)
      sections.push(
        'No standalone notice shipped in this package; refer to its package metadata and upstream source.\n',
      );
  }
}
const store = 'node_modules/.pnpm';
for (const entry of fs.readdirSync(store)) {
  const modules = path.join(store, entry, 'node_modules');
  if (!fs.existsSync(modules)) continue;
  for (const name of fs.readdirSync(modules)) {
    const candidates = name.startsWith('@')
      ? fs
          .readdirSync(path.join(modules, name))
          .map((n) => path.join(modules, name, n))
      : [path.join(modules, name)];
    for (const directory of candidates) {
      const manifest = path.join(directory, 'package.json');
      if (!fs.existsSync(manifest)) continue;
      const pkg = JSON.parse(fs.readFileSync(manifest, 'utf8'));
      addPackage(directory, pkg.name, pkg.version, pkg.license);
    }
  }
}
const metadataPath = process.argv[2] ?? '.tools/cargo-metadata.json';
if (!fs.existsSync(metadataPath))
  throw new Error(
    'Generate cargo metadata first: see README. Rust notices are mandatory.',
  );
const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
for (const pkg of metadata.packages) {
  if (pkg.source === null) continue;
  const windowsPath = pkg.manifest_path.replace(
    /^\/mnt\/([a-z])\//,
    (_, drive) => `${drive.toUpperCase()}:/`,
  );
  addPackage(path.dirname(windowsPath), pkg.name, pkg.version, pkg.license);
}
fs.mkdirSync('docs', { recursive: true });
fs.writeFileSync('docs/third-party-licenses.txt', sections.join(''), 'utf8');
console.log(`Wrote full notices for ${seen.size} installed npm/Rust packages.`);
